mapper.select:
select a.id as id, a.quotation_code as quotationCode, b.`name` as customerName, c.nick_name as salesmanName, a.create_time as createTime, a.update_time as updateTime, a.procurement_cost as procurementCost, a.procurement_cost_state as procurementCostState, a.logistics_cost as logisticsCost, a.logistics_cost_state as logisticsCostState, a.total_cost as totalCost, a.total_cost_state as totalCostState, a.order_amount orderAmount, a.status as status, a.shift_status as shiftStatus, a.currency as currency, a.tax as tax, a.fob as fob, a.exw as exw, a.exchange_rate as exchangeRate
FROM sal_sed_quotation a left join sal_yt_customer b on a.customer_id=b.id LEFT JOIN sys_user c on b.belong_employee_id =c.user_id WHERE a.is_deleted = 0
AND a.quotation_code LIKE CONCAT('%', #{quotationCode}, '%')
AND b.`name` LIKE CONCAT('%', #{customerName}, '%')
AND a.status =#{status}
AND a.status IN ('5', '6', '8')
AND a.status IN ('5', '7')
AND a.create_time >= #{createStartTime}
AND a.create_time <= #{createEndTime}
AND a.update_time >= #{lastEditStartTime}
AND a.update_time <= #{lastEditEndTime}
order by a.create_time desc

mapper.update:
UPDATE sal_sed_quotation
SET logistics_cost=#{logisticsCost},
 logistics_cost_state='1',
 logistics_remark=#{logisticsRemark}
WHERE id= #{id}
